// PGDEI Papers IV and V (speech-language-communication; family and community) and the IEIP practical. Written in Learn Anywhere's own words.
window.LIB_EXTRA = (window.LIB_EXTRA || []).concat([
{
  id:"speech-language-basics", title:"Communication, language and speech: basic concepts and the speech mechanism", subject:"Early Intervention: Speech and language", region:"Speech and language", stages:"steps",
  aliases:["communication language speech","components of language","phonology morphology syntax semantics pragmatics","speech production mechanism","anatomy of speech","form content use"],
  simple:"Communication is any sharing of messages, language is the rule-based code we use to share them, and speech is the spoken, motor way of producing that code. Language has five parts: sounds, word parts, sentence rules, meaning and social use. Speech needs breathing, voice, resonance and articulation working together under brain control.",
  flow:["Idea and intent to communicate (cognition)","Language coded in the brain: form, content, use","Respiration supplies air from the lungs","Phonation: vocal folds vibrate in the larynx","Resonance and articulation shape sounds in mouth and nose","Hearing and feedback monitor and correct the message"],
  exam:[
    {h:"Definitions", p:["Communication: the exchange of information, ideas and feelings between a sender and receiver; it can be verbal or non-verbal (gesture, eye gaze, facial expression, signs, pictures).","Language: a socially shared, rule-governed system of arbitrary symbols used in combination to represent ideas; it can be spoken, written or signed.","Speech: the neuromuscular act of producing spoken language sounds. A child can have language without speech (signing) and speech without much language (echolalia)."]},
    {h:"Components of language (Bloom and Lahey: form, content, use)", p:["Form - phonology: the sound system and rules for combining sounds (e.g. which consonant clusters are allowed).","Form - morphology: the smallest units of meaning (free morphemes like 'cat', bound morphemes like plural '-s' or past '-ed').","Form - syntax: rules for ordering words into sentences.","Content - semantics: word and sentence meaning, vocabulary and concepts.","Use - pragmatics: social rules: turn taking, greeting, requesting, topic maintenance, adjusting to the listener."]},
    {h:"Speech production subsystems", p:["Respiration: lungs, diaphragm and intercostals give a steady outgoing air stream; speech uses a quick inspiration and a long controlled expiration.","Phonation: the larynx; vocal folds are brought together and vibrate (Bernoulli effect) to make voice; pitch depends on fold tension and length.","Resonance: pharynx, oral and nasal cavities filter the voice; the velopharyngeal valve (soft palate) separates oral and nasal sounds.","Articulation: lips, tongue, teeth, jaw, hard and soft palate shape vowels and consonants by place and manner."]},
    {h:"Neural control", p:["Language areas: Broca area (expression, left inferior frontal) and Wernicke area (comprehension, left superior temporal) joined by the arcuate fasciculus.","Motor control: primary motor cortex, basal ganglia and cerebellum for coordination; cranial nerves V, VII, IX, X and XII supply the speech muscles.","Hearing is the main feedback loop; a child who cannot hear well cannot learn spoken language normally."]},
    {h:"Early intervention implications", p:["Infants communicate long before speech: crying, eye contact, smiles, gestures; treat these as real messages and respond.","Problems in any subsystem point to different causes: breathing (prematurity, CP), velopharynx (cleft palate), oral motor (CP, feeding difficulty), hearing loss.","Home activity: face-to-face play, naming objects during daily routines, copying the baby's sounds and waiting for a reply."]},
    {h:"Conclusion", p:["Separating communication, language and speech lets the interventionist locate a child's difficulty and choose the right route, including non-speech communication when needed."]}
  ],
  tip:"Draw a sagittal section of the head and neck labelling lungs, larynx (vocal folds), pharynx, soft palate, oral and nasal cavities, tongue and lips, with arrows for the air stream. Add a box listing the four subsystems.",
  evidence:[["Responsive, language-rich adult-child talk","More conversational turns linked to better language and brain activity in language areas","Moderate"],["Parent-implemented language strategies","Improve expressive language in young children with delays","Moderate"],["Early hearing identification","Better language outcomes when hearing loss is found and managed early","Moderate"]],
  evidenceSource:"Romeo et al. 2018 (Psychological Science); Roberts and Kaiser 2011 meta-analysis; Yoshinaga-Itano et al. 1998 (Pediatrics)",
  outcomes:[["Communication milestones checklist","Whether pre-verbal and verbal skills match age"],["Oral peripheral (oral motor) examination","Structure and function of lips, tongue, palate"],["Hearing screen (OAE/ABR)","Whether the main feedback channel works"]],
  recent:["Romeo et al. (2018, Psychological Science) linked the number of adult-child conversational turns, more than words heard alone, to activation of Broca area in young children."],
  mnemonic:{word:"PMSSP", items:[["P","Phonology: sounds"],["M","Morphology: word parts"],["S","Syntax: word order"],["S","Semantics: meaning"],["P","Pragmatics: social use"]], extra:"Speech subsystems: 'Real People Read Aloud' = Respiration, Phonation, Resonance, Articulation."},
  example:"A 2-year-old with a repaired cleft palate in Guntur understands simple commands and points to pictures, but his speech is nasal and hard to follow: his language is developing, while resonance and articulation are affected.",
  flags:["No response to sound or name (rule out hearing loss)","Nasal regurgitation of feeds or very nasal voice (velopharyngeal problem, submucous cleft)","Persistent hoarse voice or noisy breathing in an infant (airway or laryngeal cause; ENT referral)"],
  viva:[["Differentiate language and speech.","Language is the rule-based symbol code (spoken, written or signed); speech is the motor act of producing spoken sounds."],["What are the components of language?","Phonology, morphology, syntax (form), semantics (content) and pragmatics (use)."],["Name the cranial nerves important for speech.","Trigeminal (V), facial (VII), glossopharyngeal (IX), vagus (X) and hypoglossal (XII)."]],
  refs:[{b:"owens",ch:"Describing language; language components"},{b:"guyton",ch:"Respiration and the larynx"},{b:"inderbir",ch:"Cerebral cortex: language areas"},{c:"Romeo RR, et al. Beyond the 30-million-word gap: children's conversational exposure is associated with language-related brain function. Psychol Sci. 2018;29(5):700-710.", q:"Romeo conversational turns Broca 2018"}],
  keywords:"communication language speech components phonology morphology syntax semantics pragmatics speech mechanism",
  mcq:[["The social use of language, such as turn taking and requesting, is called:",["Semantics","Pragmatics","Morphology","Phonology"],1,"Pragmatics covers the rules for using language in social context."],["Vibration of the vocal folds to produce voice is:",["Respiration","Resonance","Phonation","Articulation"],2,"Phonation happens at the larynx when the vocal folds vibrate."]]
},
{
  id:"speech-language-development", title:"Speech and language development from birth: prerequisites, acquisition and stages", subject:"Early Intervention: Speech and language", region:"Speech and language", stages:"steps",
  aliases:["language milestones","stages of speech development","prelinguistic stage","babbling","first words","prerequisites for speech"],
  simple:"Babies learn to talk by hearing language, watching faces and taking turns with caring adults. They move from crying and cooing to babbling, first words around one year, two-word phrases by two and simple sentences by three. Good hearing, an intact brain and speech organs, and a talking environment are all needed.",
  flow:["Prerequisites: hearing, vision, brain, oral structures, social environment","Birth-3 months: crying, cooing, social smile","4-12 months: babbling, gestures, joint attention","12-18 months: first words, pointing to ask","18-24 months: word spurt, two-word phrases","2-5 years: sentences, grammar, clear speech, conversation"],
  exam:[
    {h:"Introduction", p:["Language is acquired, not taught formally; it unfolds when a ready child (biology) meets a responsive environment (people who talk with them).","Theories: behaviourist (Skinner, imitation and reinforcement), nativist (Chomsky, inborn language acquisition device), cognitive (Piaget, language follows thought), social interactionist (Vygotsky, Bruner, learning through supported interaction). Interactionist views guide early intervention."]},
    {h:"Prerequisites", p:["Biological: adequate hearing, vision, intact central nervous system, normal oral-motor structures, general health and nutrition.","Cognitive: attention, object permanence, cause and effect, imitation, symbolic play.","Social: attachment, eye contact, joint attention, turn taking, a language-rich home with responsive caregivers."]},
    {h:"Stages and milestones (approximate)", p:["0-3 months: reflexive cry, comfort sounds, cooing (vowel-like sounds) around 6-8 weeks, social smile, quiets to voice.","4-6 months: laughs, vocal play, turns to sound source, early babbling.","6-10 months: canonical babbling ('bababa'), then variegated babbling; responds to name; understands 'no'.","9-12 months: gestures (waving, showing, pointing), jargon with sentence-like intonation, first true word around 12 months.","12-18 months: slow growth of single words, follows one-step commands, points to body parts.","18-24 months: vocabulary spurt to about 50 words and beyond, two-word combinations ('mummy go').","2-3 years: three-word sentences, pronouns, plurals, 'what/where' questions; speech about half to three quarters intelligible to strangers.","3-5 years: complex sentences, storytelling, most sounds correct; speech largely intelligible to strangers by about 4 years."]},
    {h:"Development of each component", p:["Phonology: vowels and early consonants (p, b, m, n, t, d) first; later sounds (r, l, s, sh, clusters) mature by 5-7 years; normal phonological processes (fronting, final consonant deletion) fade with age.","Semantics: from object names to actions, attributes and concepts; overextension ('dog' for every animal) is normal early.","Morphology and syntax: single words, two-word semantic relations, then grammatical markers; mean length of utterance (MLU) grows with age.","Pragmatics: from intentional gestures to requesting, commenting, asking questions, turn taking and storytelling."]},
    {h:"Early intervention implications", p:["Use milestones as a screening guide and refer early; do not 'wait and see' when red flags appear.","Bilingual and multilingual Indian homes do not cause delay; encourage parents to use the language they are most fluent in.","Home activities: talk during bathing, feeding and dressing; sing rhymes; read picture books; imitate the baby's sounds and wait; follow the child's interest."]},
    {h:"Conclusion", p:["Knowing the typical sequence lets the interventionist spot delay early and set the next developmentally appropriate target."]}
  ],
  tip:"Draw a horizontal timeline from 0 to 5 years with key milestones (coo, babble, first word, 50 words and 2-word phrase, sentences) and red flags marked underneath in a second row.",
  evidence:[["Shared picture-book reading (dialogic reading)","Improves vocabulary in young children","Moderate"],["Parent-implemented responsive strategies","Improve expressive language in toddlers with delay","Moderate"],["Screen time in infancy","Associated with poorer language; advise limiting it under 2 years","Expert opinion"]],
  evidenceSource:"Roberts and Kaiser 2011 (AJSLP); AAP media guidance; Owens Language Development",
  outcomes:[["REELS or LEST","Receptive and expressive language age"],["Vocabulary checklist (e.g. MacArthur-Bates CDI)","Words understood and said"],["Language sample and MLU","Grammar and sentence length"]],
  recent:["CATALISE consensus (Bishop et al. 2016-2017) recommends monitoring late talkers and referring when red flags or risk factors are present, rather than labelling too early."],
  mnemonic:{word:"1-2-3 rule", items:[["1 year","First words"],["2 years","Two-word phrases"],["3 years","Three-word sentences"]], extra:"Red flags: no babble by 12 months, no words by 16 months, no two-word phrases by 24 months, any loss of language at any age."},
  example:"An 18-month-old girl in an Anganwadi in Mysuru points, waves and understands 'give me the ball' but says only 4 words. She is monitored with a home language plan; if there are no two-word phrases by 24 months she is referred to the DEIC.",
  flags:["No babbling by 12 months or no single words by 16 months","No spontaneous two-word phrases by 24 months","Loss of any previously gained words or social skills (autism, neurological regression)","Not responding to name or sounds"],
  viva:[["When does canonical babbling begin?","Around 6-10 months; its absence after 10-12 months is a red flag, often for hearing loss."],["What is overextension?","Using a word for a wider category than adults do, e.g. calling all animals 'dog'; normal in early vocabulary."],["Does bilingualism cause language delay?","No. Total vocabulary across both languages is age appropriate; parents should use the language they speak best."]],
  refs:[{b:"owens",ch:"Language development stages: infant to preschool"},{b:"hurlock",ch:"Speech development"},{b:"berk",ch:"Language development"},{c:"Bishop DVM, et al. Phase 2 of CATALISE: a multinational and multidisciplinary Delphi consensus study of problems with language development. J Child Psychol Psychiatry. 2017;58(10):1068-1080.", q:"CATALISE phase 2 Bishop 2017"}],
  keywords:"speech language development milestones babbling first words prerequisites stages",
  mcq:[["Two-word combinations typically appear by about:",["9 months","12 months","24 months","36 months"],2,"Most children combine two words by 18-24 months; absence at 24 months is a red flag."],["Which is a prerequisite for spoken language?",["Walking","Adequate hearing","Toilet training","Reading"],1,"Hearing is the main input and feedback channel for spoken language."]]
},
{
  id:"communication-disorders", title:"Communication disorders in young children: nature, causes, prevalence and classification", subject:"Early Intervention: Speech and language", region:"Speech and language", stages:"steps",
  aliases:["speech and language disorders","classification of communication disorders","delayed speech","hearing impairment in children","DLD","causes of speech delay"],
  simple:"A communication disorder is a problem with hearing, understanding or using language, or with producing speech. In young children it may come from hearing loss, intellectual disability, autism, cerebral palsy, cleft palate, poor stimulation or unknown causes. Problems are grouped as language, speech sound, fluency, voice, resonance and hearing disorders.",
  flow:["Risk factors: prenatal, perinatal, postnatal, environmental","Disorder affects hearing, language, speech or social use","Signs: delayed milestones, unclear speech, poor understanding","Classify: language, speech sound, fluency, voice, resonance, hearing","Screen hearing; refer to SLP and audiologist","Early, family-based intervention and follow-up"],
  exam:[
    {h:"Definition and nature", p:["A communication disorder is an impairment in the ability to receive, send, process or understand concepts or verbal, non-verbal and graphic symbol systems (ASHA wording, paraphrased).","It may be developmental or acquired, primary (no other cause, e.g. DLD) or secondary (part of another condition such as hearing loss, autism, intellectual disability or CP)."]},
    {h:"Causes in young children", p:["Prenatal: genetic syndromes (Down syndrome), TORCH infections, maternal drugs, cleft lip and palate, inner-ear malformation.","Perinatal: prematurity, low birth weight, birth asphyxia, severe neonatal jaundice, NICU stay with ototoxic drugs.","Postnatal: meningitis, recurrent middle-ear infection with effusion, head injury, mumps or measles (hearing loss).","Environmental: low stimulation, neglect, excess screen time; often adds to a biological cause.","Unknown: many children with developmental language disorder have no identifiable cause; family history is common."]},
    {h:"Prevalence and incidence", p:["Prevalence is the number of existing cases at a time; incidence is the number of new cases in a period.","Language problems are among the commonest developmental concerns in preschool children; Tomblin et al. (1997) found specific language impairment in about 7 percent of kindergarten children.","Permanent hearing loss is found in roughly 1-3 per 1000 newborns, more in NICU graduates; this is why universal newborn hearing screening is advised.","Indian figures vary between studies and survey methods; quote a study only if you know it."]},
    {h:"Range and classification", p:["Language disorders: receptive, expressive or mixed; developmental language disorder; language disorder with autism, intellectual disability or hearing loss.","Speech sound disorders: articulation (motor production of sounds) and phonological (sound pattern rules).","Motor speech disorders: dysarthria (weak or poorly coordinated muscles, e.g. CP) and childhood apraxia of speech (planning problem).","Fluency: developmental stuttering; voice: hoarseness, vocal nodules; resonance: hypernasality in cleft palate.","Hearing impairment: conductive, sensorineural or mixed; graded by decibel loss; RPwD Act 2016 lists 'deaf' (70 dB or more in speech frequencies, both ears) and 'hard of hearing' (60-70 dB)."]},
    {h:"Identification and early intervention implications", p:["Screen every high-risk infant's hearing (OAE then ABR); RBSK lists congenital deafness among defects at birth.","Watch milestones and red flags; refer to audiologist and speech-language pathologist without delay.","Treat middle-ear disease; fit hearing aids early; discuss cochlear implant candidacy for profound loss.","Families learn responsive strategies at home; consider AAC for children who cannot yet speak."]},
    {h:"Conclusion", p:["Early identification within the first 1000 days, using the 1-3-6 goal for hearing, gives the best chance of near-typical communication."]}
  ],
  tip:"Draw a tree: 'Communication disorders' branching to Hearing, Language (receptive/expressive), Speech (articulation-phonology, motor speech, fluency, voice, resonance). Put causes in a prenatal-perinatal-postnatal table beside it.",
  evidence:[["Universal newborn hearing screening with early amplification","Better language outcomes than late identification","Moderate"],["Speech and language therapy for primary expressive and phonological delay","Effective for expressive vocabulary and phonology; less clear for receptive difficulties","Moderate"],["Grommets for persistent otitis media with effusion","Short-term hearing gain; small long-term language benefit","Moderate"]],
  evidenceSource:"Law, Garrett and Nye Cochrane review 2003; JCIH 2019 position statement; Yoshinaga-Itano et al. 1998",
  outcomes:[["OAE and ABR (BERA)","Presence and degree of hearing loss"],["REELS / LEST","Language age compared with chronological age"],["Percentage consonants correct, intelligibility rating","Severity of speech sound disorder"]],
  recent:["CATALISE consensus (2016-2017) adopted 'developmental language disorder' (DLD), a term now also used in ICD-11.","JCIH 2019 position statement keeps the 1-3-6 goal: screen by 1 month, diagnose by 3 months, intervene by 6 months, and encourages faster timelines where possible."],
  mnemonic:{word:"LSFVRH", items:[["L","Language"],["S","Speech sound"],["F","Fluency"],["V","Voice"],["R","Resonance"],["H","Hearing"]], extra:"Hearing goal: 1-3-6 (screen, diagnose, intervene by months 1, 3, 6)."},
  example:"A 30-month-old boy from a NICU in Hyderabad, treated for severe jaundice, has no words and does not turn to his name. ABR shows bilateral severe sensorineural hearing loss; he is fitted with hearing aids and enrolled in a family-centred auditory-verbal programme.",
  flags:["No response to loud sounds or name at any age","Loss of words or social skills","Hypernasal speech with nasal regurgitation (cleft or submucous cleft)","Ear discharge or recurrent ear infection with speech delay"],
  viva:[["Differentiate prevalence and incidence.","Prevalence is all existing cases at a point in time; incidence is new cases occurring over a period."],["Articulation versus phonological disorder?","Articulation is a motor difficulty producing a sound; phonological is a rule-based pattern of errors in the sound system."],["What is the 1-3-6 goal?","Hearing screening by 1 month, diagnosis by 3 months and intervention by 6 months of age."]],
  refs:[{b:"owens",ch:"Language disorders in children"},{b:"batshaw",ch:"Hearing and communication disorders"},{c:"Joint Committee on Infant Hearing. Year 2019 Position Statement: Principles and Guidelines for Early Hearing Detection and Intervention Programs. J Early Hear Detect Interv. 2019;4(2):1-44.", q:"JCIH 2019 position statement early hearing detection"},{c:"Tomblin JB, et al. Prevalence of specific language impairment in kindergarten children. J Speech Lang Hear Res. 1997;40(6):1245-1260.", q:"Tomblin 1997 prevalence specific language impairment kindergarten"}],
  keywords:"communication disorders causes prevalence classification hearing impairment speech delay DLD",
  mcq:[["Childhood apraxia of speech is mainly a problem of:",["Hearing","Motor planning of speech","Vocal fold vibration","Vocabulary only"],1,"CAS is a disorder of planning and programming speech movements."],["Under RPwD Act 2016, 'deaf' refers to a hearing loss in speech frequencies of:",["26 dB in one ear","40 dB in both ears","70 dB or more in both ears","90 dB in one ear"],2,"The Act defines deaf as 70 dB or more in speech frequencies in both ears."]]
},
{
  id:"speech-language-assessment", title:"Speech and language assessment in early intervention", subject:"Early Intervention: Speech and language", region:"Speech and language", stages:"steps",
  aliases:["REELS","language assessment tools","informal assessment","family centred assessment","assessment vs evaluation","LEST"],
  simple:"Assessment means collecting information about how a child hears, understands, uses and produces language, so we can decide whether there is a problem and what to work on. We use formal tests, checklists, observation of play and parent report. Families take part as partners, and results are shared with them clearly and kindly.",
  flow:["Referral concern and case history","Hearing screen and oral-motor examination","Formal tools (REELS, LEST) and informal observation","Parent report and family priorities","Interpret, write report, share results with family","Plan goals; re-assess and evaluate outcomes"],
  exam:[
    {h:"Definition and purposes", p:["Assessment: the ongoing process of gathering information about a child's communication strengths and needs, in context, to make decisions.","Purposes: screening, diagnosis (is there a disorder and what kind), establishing a baseline, planning goals, monitoring progress, eligibility for services and certification."]},
    {h:"Methods of collecting data", p:["Case history: pregnancy, birth, medical, developmental, family history of hearing loss or speech problems, languages spoken at home.","Observation of free play and caregiver-child interaction in natural settings.","Parent interview and parent-report checklists.","Direct testing with standardised or criterion-referenced tools; language sample analysis; oral peripheral examination; hearing assessment (OAE, ABR, behavioural audiometry)."]},
    {h:"Tools", p:["Formal (standardised or norm-based): REELS (Receptive-Expressive Emergent Language Scale, Bzoch and League, birth to 3 years), Preschool Language Scale, Rossetti Infant-Toddler Language Scale.","Indian tools: LEST (Language Evaluation Scale Trivandrum, 0-6 years), developmental tools with language items such as DASII, MDPS and the Portage checklist.","Informal: milestone checklists, language sample and MLU, communication functions checklist, play-based assessment, structured observation of gestures and joint attention.","Select tools by age, purpose, cultural and language fit, reliability, validity and time available."]},
    {h:"Family-centred assessment", p:["Parents are active partners: they describe the child at home, choose priorities and can be present or help administer items.","Assess in familiar settings and routines; ask about family concerns, priorities and resources.","Use the home language and local materials; avoid labelling a bilingual child as delayed in one language alone."]},
    {h:"Communicating results; assessment versus evaluation", p:["Explain findings in plain language: strengths first, then needs, what it means and what happens next; give a written summary; allow questions.","Assessment gathers information about the child at a point in time to plan; evaluation judges the value or outcome, e.g. whether the programme achieved its goals or whether the child is eligible.","Assessment is ongoing and descriptive; evaluation is periodic and judgemental (decides worth or progress)."]},
    {h:"Conclusion", p:["Good assessment is multi-method, family-centred and linked directly to intervention goals."]}
  ],
  tip:"Draw a cycle: Screen - Assess - Plan - Intervene - Monitor - Evaluate, with the family in the centre. Add a two-column table of assessment versus evaluation.",
  evidence:[["Parent-report vocabulary checklists","Valid and practical estimate of toddler vocabulary","Moderate"],["Universal newborn hearing screening","Earlier diagnosis of hearing loss","Strong"],["Multi-method, family-centred assessment","Recommended practice for accurate, usable results","Expert opinion"]],
  evidenceSource:"JCIH 2019; DEC Recommended Practices 2014; Owens and Bzoch-League test manuals",
  outcomes:[["REELS receptive and expressive quotient","Language level relative to age"],["Language sample (MLU, word types)","Spontaneous grammar and vocabulary"],["Family concerns and priorities list","What matters to the family for goal setting"]],
  recent:["The Division for Early Childhood (DEC) Recommended Practices (2014) stress assessment in natural environments with families as partners."],
  mnemonic:{word:"SADPE", items:[["S","Screening"],["A","Assessment (diagnosis)"],["D","Data for baseline"],["P","Planning goals"],["E","Evaluation of progress"]], extra:"Assessment describes; evaluation judges."},
  example:"A 2-year-old in Secunderabad is assessed at home: mother reports 10 words; REELS gives receptive age 18 months and expressive age 12 months; OAE is normal. Results are shared with both parents in Telugu with a written summary and three agreed goals.",
  flags:["Do not skip hearing assessment in any child with language delay","Regression of language or social skills needs paediatric and autism evaluation","Avoid assessing a frightened or unwell child; results will underestimate ability"],
  viva:[["What is REELS?","Receptive-Expressive Emergent Language Scale (Bzoch and League), a parent-interview based scale for birth to 3 years giving receptive and expressive language ages."],["Difference between assessment and evaluation?","Assessment gathers information to describe the child and plan; evaluation judges outcome, eligibility or programme effectiveness."],["Why family-centred assessment?","Parents know the child best, results reflect real life, and families are more invested in the goals."]],
  refs:[{b:"owens",ch:"Assessment of language"},{b:"batshaw",ch:"Early intervention assessment"},{b:"hanen",ch:"Observing your child's communication"},{c:"Division for Early Childhood. DEC Recommended Practices in Early Intervention/Early Childhood Special Education 2014.", u:"https://www.dec-sped.org/dec-recommended-practices"}],
  keywords:"speech language assessment REELS LEST formal informal family centred assessment evaluation",
  mcq:[["REELS is designed for children aged:",["Birth to 3 years","3 to 6 years","6 to 12 years","Adolescents"],0,"REELS covers emergent language from birth to about 3 years."],["Which is an informal assessment method?",["Standardised norm-referenced test","Language sample analysis","Audiometry","IQ test"],1,"Language sampling in play is informal and gives natural data."]]
},
{
  id:"speech-language-intervention", title:"Speech and language intervention in early intervention: techniques, goals and parent guidance", subject:"Early Intervention: Speech and language", region:"Speech and language", stages:"steps",
  aliases:["parallel talk","self talk","expansion","language stimulation techniques","speech therapy goals","parent guidance speech"],
  simple:"Intervention turns assessment findings into goals and daily practice. Parents and therapists use simple strategies such as talking about what they or the child are doing, copying and expanding the child's words, and waiting for the child to take a turn. Goals are set for the short and long term, progress is checked, and children who need more are referred to a speech-language pathologist.",
  flow:["Link assessment findings to needs and priorities","Set long-term goals and SMART short-term objectives","Choose strategies: self talk, parallel talk, expansion, modelling","Coach parents to use them in daily routines","Monitor data; refer to SLP or audiologist when needed","Evaluate child and family outcomes; revise the plan"],
  exam:[
    {h:"Linking assessment with intervention", p:["Start from the child's current level (baseline) and the next step in typical development, plus what the family wants most.","Choose functional targets the child can use daily (e.g. requesting 'more', naming family members)."]},
    {h:"General techniques and strategies", p:["Self talk: the adult describes what the adult is doing ('I am cutting the mango').","Parallel talk: the adult describes what the child is doing ('You are pushing the car').","Imitation: copy the child's sounds or actions to start turn taking.","Expansion: repeat the child's utterance in a grammatically complete form ('car go' -> 'the car is going').","Extension (expatiation): add new information ('Yes, the red car is going fast').","Modelling and focused stimulation: say the target word many times in meaningful play without demanding imitation.","Recasting, communication temptations (sabotage, out-of-reach items), waiting with expectant look, choices; Hanen 'OWL' (Observe, Wait, Listen).","Milieu teaching: follow the child's lead and prompt within natural routines."]},
    {h:"Goals, IEIP and implementation", p:["Long-term goal (6-12 months): e.g. 'Child will use 50 words and two-word phrases to communicate needs at home'.","Short-term objectives (SMART: specific, measurable, achievable, relevant, time-bound): e.g. 'Child will request 5 foods using a word or sign in 4 of 5 meal opportunities within 6 weeks'.","Sessions once or twice a week with daily home practice in routines (meal, bath, play, outing)."]},
    {h:"Parent guidance and referral", p:["Coach, do not just demonstrate: model, let the parent try, give feedback, review video if possible.","Advice: face the child at eye level, reduce questions and commands, talk in short sentences, limit screens, read daily, respond to all attempts.","Refer to a speech-language pathologist for stuttering, voice problems, cleft palate speech, suspected apraxia, severe or persistent delay; to an audiologist for any hearing doubt; to a paediatrician or psychologist for autism or regression."]},
    {h:"Monitoring and evaluating outcomes", p:["Record baseline and regular data (frequency counts, word lists, video samples).","Review short-term objectives every 4-6 weeks and the plan about every 6 months; summarise child outcomes and family outcomes (parent confidence, use of strategies)."]},
    {h:"Conclusion", p:["Parent-implemented, naturalistic intervention embedded in routines is the core of early speech and language intervention, with specialist referral where needed."]}
  ],
  tip:"Make a two-column table: technique and an example sentence for each (self talk, parallel talk, expansion, extension, modelling). Examiners reward clear examples.",
  evidence:[["Parent-implemented language intervention","Positive effects on expressive language and parent strategy use","Moderate"],["Enhanced milieu teaching","Improves language in children with delays","Moderate"],["SLT for primary expressive and phonological delay","Effective; weaker evidence for receptive problems","Moderate"],["Oral motor exercises without speech (blowing, tongue push)","Do not improve speech sounds","Weak"]],
  evidenceSource:"Roberts and Kaiser 2011 meta-analysis (AJSLP); Law, Garrett and Nye Cochrane 2003; Hanen It Takes Two to Talk",
  outcomes:[["Number of words and word combinations used","Expressive progress"],["Goal attainment scaling","Achievement of individual goals"],["Parent strategy checklist","Whether parents use techniques in routines"]],
  recent:["Roberts and Kaiser (2011) meta-analysis supports training parents as the main agents of early language intervention.","Telepractice coaching of parents became widely used after COVID-19 and is now a routine option in Indian centres."],
  mnemonic:{word:"OWL", items:[["O","Observe the child's interest"],["W","Wait for the child to start"],["L","Listen to what the child says"]], extra:"Self talk = 'I'; parallel talk = 'you'."},
  example:"A mother of a 26-month-old in Warangal learns parallel talk and expansion at meal time. When her son says 'more dosa' she replies 'You want more dosa. Here is more hot dosa'. After 8 weeks he uses 30 words and 6 two-word phrases.",
  flags:["Do not delay hearing assessment while giving speech stimulation","Persistent drooling, choking or chest infections during feeding: swallowing assessment","Stuttering with tension, fear or avoidance: early SLP referral","Plateau or regression despite therapy: re-evaluate diagnosis"],
  viva:[["Define expansion with an example.","Repeating the child's utterance in a more complete adult form, e.g. child 'doggy run', adult 'the doggy is running'."],["Self talk versus parallel talk?","Self talk describes the adult's own actions; parallel talk describes the child's actions."],["When will you refer to an SLP?","Stuttering, voice or resonance problems, suspected apraxia, cleft speech, severe or persistent delay, or no progress with home strategies."]],
  refs:[{b:"hanen",ch:"Strategies to help your child talk"},{b:"owens",ch:"Language intervention"},{c:"Roberts MY, Kaiser AP. The effectiveness of parent-implemented language interventions: a meta-analysis. Am J Speech Lang Pathol. 2011;20(3):180-199.", q:"Roberts Kaiser 2011 parent-implemented language interventions meta-analysis"},{c:"Law J, Garrett Z, Nye C. Speech and language therapy interventions for children with primary speech and language delay or disorder. Cochrane Database Syst Rev. 2003;(3):CD004110.", q:"Law Garrett Nye Cochrane speech language therapy primary delay"}],
  keywords:"speech language intervention parallel talk self talk expansion modelling goals parent guidance SLP referral",
  mcq:[["A child says 'ball fall'; the adult says 'The ball fell down'. This is:",["Self talk","Expansion","Parallel talk","Sabotage"],1,"Expansion restates the child's words in a fuller grammatical form."],["Which short-term objective is SMART?",["Improve speech","Talk better at home","Name 5 family members in 4 of 5 trials within 6 weeks","Say more words"],2,"It is specific, measurable and time-bound."]]
},
{
  id:"aac", title:"Augmentative and alternative communication (AAC) for young children", subject:"Early Intervention: Speech and language", region:"Speech and language", stages:"steps",
  aliases:["AAC","PECS","communication board","speech generating device","sign language","alternative communication"],
  simple:"AAC means any way of communicating that adds to or replaces speech: gestures, signs, pictures, communication boards or talking devices. It helps children with CP, autism, severe hearing loss or intellectual disability express needs now. Using AAC does not stop speech; it often helps speech grow.",
  flow:["Identify child who cannot meet needs through speech","Assess motor, vision, hearing, cognition, family priorities","Choose unaided or aided, low or high technology system","Select vocabulary and access method (point, eye gaze, switch)","Model AAC in daily routines; train family and teachers","Review, expand vocabulary and upgrade system as child grows"],
  exam:[
    {h:"Definition", p:["Augmentative: supports existing speech; alternative: replaces speech that is absent or not understandable.","An AAC system includes symbols, aids, strategies and techniques used together."]},
    {h:"Types", p:["Unaided: no external equipment - gestures, facial expression, sign language (Indian Sign Language), Makaton-style key word signing.","Aided low-tech: objects of reference, photographs, picture symbols, communication boards and books, choice boards, PECS.","Aided high-tech: speech-generating devices and tablet apps with voice output (including Indian-language apps such as Avaz)."]},
    {h:"Candidates and assessment", p:["Children with cerebral palsy (dysarthria), autism, childhood apraxia of speech, severe intellectual disability, deafblindness, severe hearing loss, or temporary loss (tracheostomy).","Assess: seating and positioning, hand function and access (direct selection by finger or eye gaze, or indirect by scanning with switches), vision and hearing, symbol understanding, communication needs and partners, family preference, cost.","No prerequisites: AAC can start in toddlers; waiting for 'readiness' is not advised."]},
    {h:"Intervention", p:["Aided language modelling: adults point to symbols while talking so the child sees AAC used.","PECS: six phases from exchanging a picture for an item to commenting; useful in autism.","Start with core and motivating vocabulary (more, stop, want, eat, go, family names); place boards in each routine.","Train parents, siblings and Anganwadi or preschool teachers; position the child well (good sitting supports access)."]},
    {h:"Early intervention implications and myths", p:["Myth: AAC stops speech. Research reviews show AAC does not hinder and often increases natural speech.","Home activities: a meal-time choice board, photo book of family, gesture for 'more' during play songs, a 'stop' sign in action rhymes."]},
    {h:"Conclusion", p:["AAC gives every child a voice now, reduces frustration and behaviour problems, and supports language and speech development."]}
  ],
  tip:"Draw a tree: AAC -> Unaided (gesture, sign) and Aided -> Low-tech (objects, pictures, boards, PECS) and High-tech (SGD, apps). Add access methods: direct selection and scanning.",
  evidence:[["AAC intervention and natural speech","Does not hinder speech; modest gains in speech for many children","Moderate"],["Augmented language intervention for toddlers with developmental delay","Supported expressive communication more than speech-only intervention","Moderate"],["PECS in autism","Improves requesting; evidence for speech and broader communication is mixed","Moderate"]],
  evidenceSource:"Millar, Light and Schlosser 2006 (JSLHR); Romski et al. 2010 (JSLHR)",
  outcomes:[["Number of communicative acts per routine","Frequency of communication"],["Communication functions used (request, reject, comment)","Breadth of communication"],["Communication Matrix","Level of expressive communication including pre-symbolic"]],
  recent:["Indian-language AAC apps and low-cost tablets have made voice-output AAC more available for young children in India."],
  mnemonic:{word:"GAPS", items:[["G","Gestures and signs (unaided)"],["A","Aided low-tech: pictures and boards"],["P","PECS"],["S","Speech-generating devices"]], extra:"AAC: Add, don't replace hope for speech."},
  example:"A 3-year-old with spastic quadriplegic CP in Vijayawada cannot speak clearly but looks at what she wants. An eye-gaze board with 4 photos (water, milk, mother, toy) on her chair lets her make choices at meals; her mother models it daily.",
  flags:["Poor seating blocks access: fix positioning before judging AAC ability","Check vision and hearing before choosing symbols","Do not withhold AAC while waiting for speech","Device without trained partners is abandoned: train family and teachers"],
  viva:[["Name types of AAC.","Unaided (gesture, sign) and aided (low-tech boards and pictures; high-tech speech-generating devices)."],["Does AAC delay speech?","No. Reviews show it does not hinder and may improve natural speech."],["What is indirect selection?","Choosing items by scanning (items offered one by one) and activating a switch, used when direct pointing is not possible."]],
  refs:[{b:"owens",ch:"Augmentative and alternative communication"},{b:"batshaw",ch:"Communication and AAC"},{c:"Millar DC, Light JC, Schlosser RW. The impact of augmentative and alternative communication intervention on the speech production of individuals with developmental disabilities: a research review. J Speech Lang Hear Res. 2006;49(2):248-264.", q:"Millar Light Schlosser 2006 AAC speech production review"},{c:"Romski M, et al. Randomized comparison of augmented and nonaugmented language interventions for toddlers with developmental delays and their parents. J Speech Lang Hear Res. 2010;53(2):350-364.", q:"Romski 2010 augmented language intervention toddlers"}],
  keywords:"AAC augmentative alternative communication PECS communication board speech generating device sign",
  mcq:[["A picture communication board is an example of:",["Unaided AAC","Aided low-tech AAC","High-tech AAC","Speech therapy only"],1,"Boards need an external aid but no electronics."],["Regarding AAC and speech, evidence shows that AAC:",["Stops speech developing","Does not hinder and may help speech","Should start only after 5 years","Is only for adults"],1,"Reviews (Millar et al. 2006) found no harm and frequent gains."]]
},
{
  id:"family-systems", title:"The family and the child: types, life cycle, dynamics and family systems", subject:"Early Intervention: Family and community", region:"Family and community", stages:"steps",
  aliases:["family systems theory","types of family","family life cycle","family dynamics","joint family","effect of disabled child on family","coping"],
  simple:"A family is a group of people linked by birth, marriage or choice who care for each other and raise children. Families change over a life cycle and work as a system, so what happens to one member, such as the birth of a child with a disability, affects everyone. Understanding a family's roles, culture, resources and coping helps the interventionist support the child through the family.",
  flow:["Define family and identify its type","Map life-cycle stage, members, roles and hierarchy","Understand culture, communication and decision making","List resources, strengths, supports and needs","Assess impact of the child's disability and coping","Plan support that fits the family system"],
  exam:[
    {h:"Definition, importance and types", p:["Family: a social unit of people related by blood, marriage or adoption, usually living together, sharing resources and caring for children.","Importance: physical care, emotional security, socialisation, values, economic support, first teacher of language and behaviour.","Types: nuclear, joint or extended (common in India), single-parent, blended or step, three-generation, foster or adoptive; also by authority (patriarchal, matriarchal) and residence."]},
    {h:"Life cycle, dynamics, hierarchy and roles", p:["Life cycle (Duvall's stages): couple, childbearing, preschool, school-age, adolescent, launching, middle-aged parents, ageing; each stage has tasks, and a disability can stall transitions.","Dynamics: patterns of interaction, alliances, boundaries (clear, rigid, diffuse), cohesion and adaptability (Olson circumplex model).","Hierarchy and roles: who decides, who earns, who gives care; in Indian joint families grandparents and elders often decide about treatment, and mothers usually carry the care load."]},
    {h:"Culture, communication and family systems", p:["Tradition and culture shape beliefs about disability (karma, fate, evil eye), child-rearing, gender roles and help seeking.","Communication patterns: open or closed, who speaks to professionals, how emotions are shown.","Family systems theory: the family is an interdependent whole; change in one part affects all. Turnbull's family systems framework: family characteristics, interactions (marital, parental, sibling, extended), functions (economic, daily care, recreation, socialisation, affection, self-esteem, education) and life cycle."]},
    {h:"Resources, needs and effect of a disabled child", p:["Resources: money, time, extended family, neighbours, religious and community groups, schemes; strengths such as faith, problem solving, cohesion.","Effects on the family: emotional reactions, extra time and cost of care, loss of income (often the mother stops work), marital strain, sibling effects (less attention, extra responsibilities, but also empathy), social isolation and stigma.","Effects on the child: family stress, overprotection or neglect reduce learning opportunities; supportive families improve development."]},
    {h:"Coping and adaptation", p:["Double ABCX model (McCubbin and Patterson): stressor plus pile-up of demands, resources, and perception (meaning) determine adaptation.","Problem-focused coping (seeking information, services) and emotion-focused coping (acceptance, prayer, reframing); social support is a strong buffer.","Interventionist role: identify strengths, connect to supports and schemes, include fathers and grandparents, respect culture, avoid blame."]},
    {h:"Conclusion", p:["The child lives within a family system; early intervention works best when it strengthens the whole family rather than treating the child alone."]}
  ],
  tip:"Draw a genogram of a joint family (squares for males, circles for females, the index child marked) and an eco-map of supports around it. Add the Double ABCX boxes.",
  evidence:[["Family-centred help-giving practices","Linked to better parent self-efficacy, wellbeing and child outcomes","Moderate"],["Social support for families of children with disability","Associated with lower parental stress","Moderate"],["Family systems-based intervention (theory application)","Recommended practice in EI","Expert opinion"]],
  evidenceSource:"Dunst, Trivette and Hamby 2007 meta-analysis; Turnbull family systems framework",
  outcomes:[["Genogram and eco-map","Structure, relationships and supports"],["Family Needs Survey (Bailey and Simeonsson)","Expressed family needs"],["Family Support Scale (Dunst)","Helpfulness of sources of support"]],
  recent:["The WHO-UNICEF Nurturing Care Framework (2018) places caregivers and families at the centre of early childhood development, including caregiver wellbeing."],
  mnemonic:{word:"CIFL (Turnbull)", items:[["C","Characteristics"],["I","Interactions"],["F","Functions"],["L","Life cycle"]], extra:"Double ABCX: a (stressor + pile-up), b (resources), c (perception) -> x (adaptation)."},
  example:"In a joint family in Karimnagar, the grandmother believes a 1-year-old's CP is due to bad luck and opposes therapy. The interventionist invites her to sessions, shows her small gains and teaches her a feeding position; she becomes the main supporter of the home programme.",
  flags:["Signs of domestic violence or child neglect: follow child protection procedures","Severe maternal depression or suicidal talk: urgent mental health referral","Family isolation with no support: link to parent groups and schemes"],
  viva:[["What is family systems theory?","The view that a family is an interconnected whole, so a change in one member, such as a child's disability, affects all members and their interactions."],["Name the Turnbull family systems components.","Family characteristics, family interactions, family functions and family life cycle."],["What does the 'c' factor mean in the ABCX model?","The family's perception or meaning of the stressful event."]],
  refs:[{b:"turnbull",ch:"Family systems framework"},{b:"dunst",ch:"Family resources and needs"},{b:"park",ch:"Family and medicine"},{c:"Dunst CJ, Trivette CM, Hamby DW. Meta-analysis of family-centered helpgiving practices research. Ment Retard Dev Disabil Res Rev. 2007;13(4):370-378.", q:"Dunst Trivette Hamby 2007 family-centered helpgiving meta-analysis"}],
  keywords:"family systems types life cycle dynamics hierarchy roles culture resources disabled child coping adaptation",
  mcq:[["In Turnbull's framework, providing affection and self-esteem are family:",["Characteristics","Interactions","Functions","Life-cycle stages"],2,"Family functions include affection, self-esteem, daily care, economics and others."],["The Double ABCX model is a model of:",["Language acquisition","Family stress and adaptation","Motor control","Group dynamics"],1,"McCubbin and Patterson's model explains family adaptation to stress."]]
},
{
  id:"parental-reactions", title:"Parents of a child with developmental delay: reactions, stress and support", subject:"Early Intervention: Family and community", region:"Family and community", stages:"steps",
  aliases:["parental reactions","stages of grief disability","parental stress","parent training","parent to parent support","chronic sorrow"],
  simple:"When parents learn their baby has a delay or disability, they often feel shock, denial, guilt, anger and sadness before slowly adapting. Many face stress, tiredness, money worries and depression, and their confidence can drop. Parent training and meeting other parents who have been through the same help them cope and help the child.",
  flow:["Diagnosis or suspicion of delay","Shock and denial","Guilt, anger, sadness and blame","Gradual adaptation and reorganisation","Ongoing stress; chronic sorrow at milestones","Support: training, counselling, parent-to-parent groups"],
  exam:[
    {h:"Impact of a child with delay on parents", p:["Emotional: grief for the expected child, fear for the future, guilt, self-blame.","Practical: repeated hospital visits, therapy time, costs, loss of employment, sleep disturbance.","Social: stigma, unhelpful advice, isolation; marital strain or, in some, closer bonds."]},
    {h:"Stages of reaction", p:["Drotar et al. (1975): shock, denial, sadness and anger, adaptation, reorganisation.","Others describe stages similar to Kubler-Ross (denial, anger, bargaining, depression, acceptance); in practice stages overlap and recur.","Olshansky (1962) described chronic sorrow: recurring grief at milestones (school entry, missed events) is normal, not pathology."]},
    {h:"Attitudes, interactions, stress and depression", p:["Attitudes range from acceptance to overprotection, rejection or unrealistic expectations; doctor shopping and faith healers are common during denial.","Parent-child interaction may become directive or less responsive; teaching responsive interaction helps the child.","Parental stress is higher in parents of children with disabilities, especially with behaviour problems or autism; mothers report more depression; low self-esteem and self-efficacy follow repeated 'failure' messages.","Screen with tools such as the Parenting Stress Index and refer for mental health care when needed."]},
    {h:"Parent training and parent-to-parent support", p:["Parent training: teaching parents developmental activities, handling, communication strategies and behaviour management, through demonstration, coaching, home visits and group sessions.","Parent-to-parent programmes: a trained 'veteran' parent supports a new parent; gives hope, practical tips and reduced isolation.","Parent associations and self-help groups also do advocacy and help families access schemes."]},
    {h:"Early intervention implications", p:["Respect the stage the parent is in; do not force acceptance; give information in small amounts and repeat.","Praise what parents do well; set small achievable home goals to rebuild confidence.","Include fathers and grandparents; offer respite information (National Trust Samarth); refer for counselling when depression is suspected."]},
    {h:"Conclusion", p:["Supporting parents' wellbeing is part of intervention: a coping, confident parent is the child's best therapist."]}
  ],
  tip:"Draw the Drotar curve: intensity of reaction on the y-axis and time on the x-axis with overlapping humps for shock, denial, sadness-anger, adaptation and reorganisation.",
  evidence:[["Parent-to-parent support","Parents report increased acceptance and coping","Moderate"],["Stress-management and cognitive-behavioural interventions for parents","Reduce parental stress and depressive symptoms","Moderate"],["Parent training in behaviour management","Reduces child behaviour problems and parent stress","Moderate"]],
  evidenceSource:"Singer et al. 1999 (J Early Intervention); Hastings and Beck 2004 (J Child Psychol Psychiatry)",
  outcomes:[["Parenting Stress Index","Level and sources of parenting stress"],["Depression screening (e.g. PHQ-9)","Parent depressive symptoms"],["Parent self-efficacy rating","Confidence in caring for the child"]],
  recent:["WHO Caregiver Skills Training programme, for families of children with developmental delays and autism, has been adapted and piloted in several countries including India."],
  mnemonic:{word:"SDSAR (Drotar)", items:[["S","Shock"],["D","Denial"],["S","Sadness and anger"],["A","Adaptation"],["R","Reorganisation"]], extra:"Chronic sorrow: grief returns at milestones; it is normal."},
  example:"A mother in Nalgonda whose 10-month-old has Down syndrome blames herself and visits several temples for a cure. The interventionist listens without judging, links her with a parent of a 5-year-old with Down syndrome, and starts simple play activities; over three months she becomes active in therapy.",
  flags:["Parent expresses hopelessness or thoughts of self-harm or harming the child: urgent referral","Signs of child neglect or abuse","Marital breakdown with no support: refer for counselling and social support"],
  viva:[["Who described stages of parental reaction to a congenital malformation?","Drotar and colleagues (1975): shock, denial, sadness and anger, adaptation, reorganisation."],["What is chronic sorrow?","Recurring grief felt by parents at key times through the child's life (Olshansky); a normal response."],["What is parent-to-parent support?","Matching a new parent with an experienced parent of a child with a similar condition for emotional and practical support."]],
  refs:[{b:"turnbull",ch:"Families and their adaptation"},{b:"batshaw",ch:"Families of children with disabilities"},{c:"Drotar D, et al. The adaptation of parents to the birth of an infant with a congenital malformation: a hypothetical model. Pediatrics. 1975;56(5):710-717.", q:"Drotar 1975 adaptation parents congenital malformation"},{c:"Hastings RP, Beck A. Practitioner review: stress intervention for parents of children with intellectual disabilities. J Child Psychol Psychiatry. 2004;45(8):1338-1349.", q:"Hastings Beck 2004 stress intervention parents intellectual disabilities"}],
  keywords:"parental reactions stages stress depression self esteem parent training parent to parent support chronic sorrow",
  mcq:[["The first stage in Drotar's model is:",["Denial","Shock","Anger","Adaptation"],1,"Drotar's sequence starts with shock."],["Recurring grief at milestones in parents of a child with disability is called:",["Chronic sorrow","Psychosis","Denial","Burnout"],0,"Olshansky termed this chronic sorrow; it is a normal reaction."]]
},
{
  id:"counselling-ei", title:"Counselling in early intervention: case work, family therapy, marital counselling and breaking the news", subject:"Early Intervention: Family and community", region:"Family and community", stages:"steps",
  aliases:["case work","Biestek principles","family therapy","marital counselling","breaking bad news","SPIKES","individual counselling"],
  simple:"Counselling helps parents understand their feelings, solve problems and make decisions about their child. Case work is a one-to-one helping method with clear principles such as acceptance and confidentiality; family therapy works with the whole family, and marital counselling with the couple. Breaking the news of a disability must be done honestly, kindly and in private, with both parents present where possible.",
  flow:["Build rapport; ensure privacy and time","Listen and understand the problem (intake and study)","Assess needs, feelings and resources","Plan goals together with the client","Intervene: counselling, information, linking to services","Evaluate, follow up and terminate"],
  exam:[
    {h:"Case work: definition and principles", p:["Social case work: a method of helping individuals and families, one at a time, to cope with problems through a professional relationship and use of resources.","Process: intake, study, diagnosis (assessment), treatment (intervention), evaluation, follow-up and termination.","Biestek's principles: individualisation, purposeful expression of feelings, controlled emotional involvement, acceptance, non-judgemental attitude, client self-determination, confidentiality."]},
    {h:"Individual counselling", p:["Core conditions (Carl Rogers): empathy, unconditional positive regard, genuineness.","Skills: active listening, open questions, reflection of feeling, paraphrasing, summarising, silence, information giving, problem solving.","Approaches: client-centred, cognitive-behavioural (changing unhelpful thoughts such as self-blame), solution-focused."]},
    {h:"Family therapy", p:["Definition: therapy that treats the family as a system and works on relationships and communication rather than one 'patient'.","Principles: circular causality, every member's view matters, focus on strengths and patterns.","Methods: structural (Minuchin, boundaries and hierarchy), strategic (Haley), Bowenian (differentiation, genograms), solution-focused; techniques include joining, reframing, enactment, setting tasks."]},
    {h:"Marital counselling", p:["Need: disability can increase marital conflict through blame, unequal care load, money and lack of time together.","Methods: joint sessions, improving communication (listening, 'I' statements), sharing care tasks, problem solving, cognitive-behavioural couple work; refer to a qualified family or marital therapist for serious conflict."]},
    {h:"Breaking the news", p:["Prepare: know the facts, private room, enough time, both parents (or a support person) present, baby present where suitable.","Use a structured approach such as SPIKES: Setting, Perception (what parents already know), Invitation (how much they want to know), Knowledge (clear, simple words, no jargon), Emotions (respond with empathy), Strategy and Summary (next steps, follow-up).","Begin with the child as a baby, not a diagnosis; mention strengths; give realistic hope and written information; arrange follow-up soon."]},
    {h:"Conclusion", p:["Counselling is an ongoing thread through early intervention, helping families move from distress to active, informed partnership."]}
  ],
  tip:"Draw the case work process as a circle (intake, study, assessment, intervention, evaluation, termination) and list Biestek's seven principles beside it. Put SPIKES as a vertical acronym.",
  evidence:[["Structured communication of diagnosis (e.g. SPIKES)","Recommended to improve parent satisfaction and understanding","Expert opinion"],["Psychological interventions for parents of children with disability","Reduce stress and improve wellbeing","Moderate"],["Family-centred help-giving","Better parent self-efficacy and wellbeing","Moderate"]],
  evidenceSource:"Baile et al. 2000 (The Oncologist); Hastings and Beck 2004; Dunst et al. 2007",
  outcomes:[["Parenting Stress Index","Change in stress after counselling"],["Goal attainment scaling","Family-set counselling goals achieved"],["Parent satisfaction with disclosure","Quality of breaking-news process"]],
  recent:["Tele-MANAS (2022), India's national tele-mental health helpline, gives families a free route to counselling support."],
  mnemonic:{word:"SPIKES", items:[["S","Setting"],["P","Perception"],["I","Invitation"],["K","Knowledge"],["E","Emotions and empathy"],["S","Strategy and summary"]], extra:"Biestek: 'I Paid Cash And Never Signed Contracts' = Individualisation, Purposeful expression, Controlled involvement, Acceptance, Non-judgemental, Self-determination, Confidentiality."},
  example:"A paediatrician and early interventionist in Hyderabad tell parents that their 4-month-old has signs of cerebral palsy. They use a private room, call the father too, ask what the parents have noticed, explain in Telugu, pause for tears, outline early therapy and book a home visit for the next week.",
  flags:["Do not break news in a corridor or by phone without follow-up","Never promise a cure or give false hope","Refer when counselling reveals severe depression, violence or substance misuse","Respect confidentiality except when a child or parent is at risk"],
  viva:[["Name Biestek's principles of case work.","Individualisation, purposeful expression of feelings, controlled emotional involvement, acceptance, non-judgemental attitude, client self-determination, confidentiality."],["What is SPIKES?","A six-step protocol for breaking bad news: Setting, Perception, Invitation, Knowledge, Emotions, Strategy and summary."],["What is the key idea of family therapy?","The family is a system; problems are understood in terms of relationships and patterns, not one individual."]],
  refs:[{b:"turnbull",ch:"Communication and collaboration with families"},{b:"dunst",ch:"Help-giving practices"},{c:"Baile WF, et al. SPIKES - a six-step protocol for delivering bad news: application to the patient with cancer. Oncologist. 2000;5(4):302-311.", q:"Baile SPIKES six-step protocol bad news 2000"}],
  keywords:"counselling case work Biestek principles family therapy marital counselling breaking bad news SPIKES",
  mcq:[["Which is one of Biestek's principles of case work?",["Directive advice","Client self-determination","Punishment","Group decision"],1,"Self-determination respects the client's right to make choices."],["In SPIKES, 'P' stands for:",["Prognosis","Perception","Planning","Prayer"],1,"Find out what the parents already know or perceive."]]
},
{
  id:"community-disability", title:"Community and disability: culture, awareness, community organisation and group work", subject:"Early Intervention: Family and community", region:"Family and community", stages:"steps",
  aliases:["community organisation","group work","group dynamics","community awareness","attitudes to disability","self help groups"],
  simple:"A community is a group of people living in one area or sharing common interests and values. Its beliefs and attitudes can include or exclude a child with disability, so awareness work, local resources and organised community action matter. Group work uses small groups, such as parent groups, to share support and learn together.",
  flow:["Understand the community: people, leaders, beliefs, resources","Identify attitudes and barriers to inclusion","Raise awareness; involve leaders, ASHA, Anganwadi","Organise: committees, self-help and parent groups","Use group work for support and learning","Mobilise resources; evaluate and sustain"],
  exam:[
    {h:"Definition and role in disability", p:["Community: people living in a defined area or sharing common interests, with a sense of belonging, shared values and institutions.","Role: early identification (Anganwadi workers, ASHAs), acceptance and inclusion, local resources and volunteers, inclusive preschools and schools, advocacy, sustainable support after professionals leave (see CBR topic for the CBR model)."]},
    {h:"Culture, values and attitudes", p:["Beliefs about disability as punishment, fate or curse, and fear of stigma, can delay help seeking and isolate families; siblings' marriage prospects may be feared.","Positive values (joint families, religious charity, neighbourhood help) can be built on.","Effects: negative attitudes reduce the child's play and school opportunities and increase parent stress; inclusive attitudes improve participation."]},
    {h:"Awareness, resources and community organisation", p:["Awareness: street plays, wall paintings, local radio, camps, school talks, celebrating International Day of Persons with Disabilities (3 December).","Resources: Anganwadis (ICDS), PHCs, DEICs, panchayats, NGOs, self-help groups, religious bodies, local businesses.","Community organisation: a process by which a community identifies its needs and takes action using its own resources. Rothman's models: locality development, social planning and social action.","Steps: study the community, identify needs, involve leaders, form committees, plan, act, evaluate."]},
    {h:"Group work", p:["Definition: a method of social work helping individuals through purposeful group experiences.","Principles: planned group formation, specific objectives, purposeful worker-group relationship, use of programme activities, democratic participation, continuous evaluation.","Types: self-help or mutual support groups (parent groups), educational groups (parent training), therapeutic groups, recreational groups, task groups (committees).","Group dynamics: interactions, roles, cohesion, norms, leadership and communication; Tuckman stages: forming, storming, norming, performing, adjourning."]},
    {h:"Early intervention implications", p:["Run monthly parent groups at the Anganwadi with play demonstrations.","Train Anganwadi workers and ASHAs to use simple screening and refer to the DEIC.","Link families to inclusive preschools and community resources; involve local leaders to reduce stigma."]},
    {h:"Conclusion", p:["Changing community attitudes and building local supports multiplies the effect of early intervention for each family."]}
  ],
  tip:"Draw Tuckman's stages as a staircase (forming, storming, norming, performing, adjourning) and a circle diagram of community resources around a family.",
  evidence:[["Parent support groups","Improved coping and reduced isolation reported by parents","Moderate"],["Community-based rehabilitation programmes","Improve participation and inclusion in low-resource settings","Weak"],["Community awareness programmes","Can improve knowledge and attitudes; long-term behaviour change less certain","Weak"]],
  evidenceSource:"Singer et al. 1999; WHO CBR guidelines 2010; Park's Preventive and Social Medicine",
  outcomes:[["Attitude survey before and after awareness","Change in community attitudes"],["Number of children identified and referred","Reach of early identification"],["Group attendance and cohesion","Function of parent groups"]],
  recent:["Accessible India Campaign (Sugamya Bharat Abhiyan, 2015) promotes accessible buildings, transport and information for persons with disabilities."],
  mnemonic:{word:"FSNPA", items:[["F","Forming"],["S","Storming"],["N","Norming"],["P","Performing"],["A","Adjourning"]], extra:"Rothman: Locality, Planning, Action (LPA)."},
  example:"In a village near Medak, the interventionist forms a mothers' group at the Anganwadi. After the 'storming' phase of complaints about services, the group agrees norms, learns play activities each month and petitions the panchayat for a ramp at the school.",
  flags:["Do not disclose a family's diagnosis to the community without consent","Watch for exclusion or abuse of children with disability in the community","Group leaders who dominate can silence vulnerable parents: manage group dynamics"],
  viva:[["Define community organisation.","A process by which a community identifies its needs, mobilises its own resources and takes collective action to meet them."],["Name Tuckman's stages of group development.","Forming, storming, norming, performing and adjourning."],["Give two community resources for early intervention in India.","Anganwadi centres under ICDS and District Early Intervention Centres under RBSK."]],
  refs:[{b:"park",ch:"Social sciences and health; community"},{b:"turnbull",ch:"Community resources and advocacy"},{c:"Tuckman BW. Developmental sequence in small groups. Psychol Bull. 1965;63(6):384-399.", q:"Tuckman 1965 developmental sequence small groups"}],
  keywords:"community disability culture attitudes awareness resources community organisation group work group dynamics",
  mcq:[["A parent self-help group is a type of:",["Task group","Mutual support group","Therapeutic hospital group","Recreational club only"],1,"Self-help groups give mutual support among people with a shared situation."],["Which is NOT one of Tuckman's stages?",["Forming","Storming","Reforming","Norming"],2,"The stages are forming, storming, norming, performing and adjourning."]]
},
{
  id:"ei-services", title:"Organising early intervention services: schemes, service models, teams and preschool linkage", subject:"Early Intervention: Family and community", region:"Family and community", stages:"steps",
  aliases:["RBSK","DEIC","RPwD Act 2016","National Trust Niramaya","UDID","transdisciplinary team","service delivery models"],
  simple:"Early intervention services in India are delivered through government programmes like RBSK and District Early Intervention Centres, laws such as the RPwD Act 2016, and National Trust schemes. Services can be home-based, centre-based, hospital-based or community-based, and are given by teams that work together in different ways. Good programmes also prepare the child to join a preschool.",
  flow:["Identify child through screening (RBSK, Anganwadi, NICU follow-up)","Refer to DEIC or EI centre; team assessment","Choose service setting: home, centre, hospital, community","Team plans IEIP; certify disability; access schemes","Deliver and monitor intervention with family","Transition to inclusive preschool or Anganwadi"],
  exam:[
    {h:"Schemes and benefits", p:["RBSK (Rashtriya Bal Swasthya Karyakram, 2013, National Health Mission): screening of children 0-18 years for 4 Ds: defects at birth, diseases, deficiencies, and developmental delays including disabilities; mobile health teams screen at Anganwadis and schools.","DEIC (District Early Intervention Centre): RBSK referral centre at the district hospital with a team (paediatrician, medical officer, physiotherapist, audiologist and speech therapist, psychologist, optometrist, special educator or early interventionist, social worker and others) for assessment and intervention.","RPwD Act 2016: 21 disabilities, benchmark disability 40 percent or more, rights to inclusive education, early detection and rehabilitation, reservation and social security.","National Trust Act 1999 (autism, CP, intellectual disability, multiple disabilities): Niramaya health insurance, Disha early intervention and school readiness, Samarth respite, Sahyogi caregiver training, legal guardianship.","Disability certificate and UDID card (Unique Disability ID) give access to benefits; ADIP scheme provides aids and appliances; state disability pensions and travel concessions."]},
    {h:"Service delivery models and settings", p:["Home-based: in natural environment, involves whole family, low cost to family, good generalisation; but fewer specialists and equipment (e.g. Portage model).","Centre-based: access to a team, equipment and peer groups; travel burden; less carry-over to home.","Hospital-based: NICU follow-up and high-risk clinics; early identification, medical care.","Community-based: Anganwadi, CBR workers, camps; wide reach in rural areas.","Combined models are common: centre assessment plus home programmes."]},
    {h:"Team models and functions", p:["Multidisciplinary: each professional assesses and treats separately; parents receive several separate plans.","Interdisciplinary: separate assessments but shared meetings and one joint plan.","Transdisciplinary: team members share and release roles; one primary service provider works with the family, backed by the team; preferred in EI because it reduces family burden.","Functions: screening, assessment, planning, intervention, family support, referral, record keeping, evaluation, transition."]},
    {h:"Organising a programme in the community and preschool linkage", p:["Steps: needs survey, involve stakeholders, identify location and team, train workers, set up referral pathways, run services, monitor and evaluate.","Linkage with preschool: transition planning from about 2.5-3 years, share child profile and strategies with the Anganwadi or preschool teacher, adapt materials and teaching strategies, support inclusion, follow up after entry."]},
    {h:"Early intervention implications", p:["Help families obtain the disability certificate and UDID, insurance and aids early; benefits often depend on paperwork.","Use transdisciplinary, home-linked services so the child gets one coherent plan."]},
    {h:"Conclusion", p:["Effective EI needs schemes, the right setting and a well-coordinated team, ending in a smooth move to inclusive education."]}
  ],
  tip:"Draw three diagrams for team models: separate boxes (multi), boxes linked by lines to one plan (inter), and overlapping circles with family in the centre (trans). Add a table of RBSK 4 Ds.",
  evidence:[["Early intervention programmes for at-risk and preterm infants","Improve cognitive outcomes in infancy and preschool","Moderate"],["Transdisciplinary primary service provider model","Recommended to reduce fragmentation; direct comparative evidence limited","Expert opinion"],["Home visiting programmes","Benefits for child development and parenting","Moderate"]],
  evidenceSource:"Spittle et al. Cochrane review of early developmental intervention for preterm infants; DEC Recommended Practices 2014",
  outcomes:[["Number screened, referred and enrolled","Programme reach"],["Child developmental quotient change (DASII)","Child outcome"],["Family outcome survey","Family knowledge, confidence and access to services"]],
  recent:["The UDID (Unique Disability ID) portal provides a single national disability card and online certification under the Department of Empowerment of Persons with Disabilities.","National Education Policy 2020 stresses early childhood care and education and inclusion of children with disabilities from the foundational stage."],
  mnemonic:{word:"4 Ds of RBSK", items:[["D","Defects at birth"],["D","Diseases"],["D","Deficiencies"],["D","Developmental delays including disabilities"]], extra:"Team models: Multi = many separate; Inter = interact for one plan; Trans = transfer roles."},
  example:"An RBSK mobile team in Khammam finds a 14-month-old not sitting. At the DEIC he is diagnosed with CP; the team gives one transdisciplinary home programme, helps the family get a UDID card and Niramaya cover, and later links him to the local Anganwadi preschool.",
  flags:["Do not delay therapy while waiting for certification","Fragmented, multi-provider care overwhelms families: coordinate","Check scheme details on official sites; benefit amounts and rules change"],
  viva:[["What are the 4 Ds of RBSK?","Defects at birth, diseases, deficiencies, and developmental delays including disabilities."],["What is role release?","In the transdisciplinary model, professionals teach and transfer selected skills to the primary provider and family."],["Which disabilities are covered by the National Trust Act 1999?","Autism, cerebral palsy, intellectual disability and multiple disabilities."]],
  refs:[{b:"park",ch:"Health programmes in India: RBSK"},{b:"ghai",ch:"Developmental delay and disability services"},{c:"Rashtriya Bal Swasthya Karyakram operational guidelines, Ministry of Health and Family Welfare, Government of India.", q:"Rashtriya Bal Swasthya Karyakram district early intervention centre"},{c:"Spittle A, Orton J, Anderson PJ, Boyd R, Doyle LW. Early developmental intervention programmes provided post hospital discharge to prevent motor and cognitive impairment in preterm infants. Cochrane Database Syst Rev. 2015;(11):CD005495.", q:"Spittle Cochrane early developmental intervention preterm infants 2015"}],
  keywords:"early intervention services RBSK DEIC RPwD National Trust Niramaya UDID service delivery models team models preschool linkage",
  mcq:[["A primary service provider supported by other professionals who release roles describes the:",["Multidisciplinary model","Interdisciplinary model","Transdisciplinary model","Medical model"],2,"Role release and one main provider define the transdisciplinary model."],["Niramaya is a scheme of the National Trust providing:",["Free school uniforms","Health insurance","Housing","Employment"],1,"Niramaya is a health insurance scheme for persons covered by the National Trust Act."]]
},
{
  id:"ieip", title:"Case history, developmental and family assessment and the Individualised Early Intervention Programme (IEIP / IFSP)", subject:"Early Intervention: Family and community", region:"Family and community", stages:"steps",
  aliases:["IEIP","IFSP","case history infant","developmental assessment 0-3","family assessment","individualised family service plan","practical exam record"],
  simple:"For every child, the interventionist takes a detailed case history, assesses development and the family's concerns and resources, then writes an individualised plan with clear goals. The plan is carried out mostly at home with the family, progress is recorded and the plan is reviewed. This is the core of the PGDEI practical exams.",
  flow:["Case history: prenatal, birth, medical, developmental, family","Developmental assessment with standard tools (DASII, Portage, TDSC)","Family assessment: concerns, priorities, resources, stress","Write IEIP: present levels, goals, strategies, who, where, when","Implement through home routines and sessions","Evaluate, record progress, review and plan transition"],
  exam:[
    {h:"Case history (0-3 years)", p:["Identifying data, informant and reliability, chief concerns in the parent's words.","Antenatal: maternal age, consanguinity, infections, drugs, bleeding, nutrition, scans.","Natal: gestation, mode and place of delivery, birth cry, birth weight, resuscitation.","Neonatal: NICU stay, jaundice, seizures, ventilation, feeding difficulty.","Post-natal and medical: illnesses, hospital admissions, immunisation, vision and hearing, current medications, feeding and sleep.","Developmental history: motor, language, social, cognitive and self-help milestones; family history (genogram), socio-economic status, home environment and daily routine."]},
    {h:"Developmental assessment", p:["Screening: TDSC, Ages and Stages; diagnostic or programming tools: DASII (motor and mental DQ), Portage checklist, MDPS, REELS for language.","Clinical examination: growth, head circumference, tone, reflexes, posture, vision, hearing.","Report: developmental age in each domain, developmental quotient (developmental age / chronological age x 100, using corrected age for preterm babies up to 2 years), strengths and needs."]},
    {h:"Family assessment", p:["Methods: interview in the home, Routines-Based Interview (McWilliam), eco-map and genogram.","Tools: Family Needs Survey (Bailey and Simeonsson), Family Support Scale (Dunst), Parenting Stress Index; NIEPID family assessment checklists where available.","Identify family concerns, priorities and resources (CPR), daily routines, stressors and supports."]},
    {h:"Writing the IEIP / IFSP", p:["Contents: child's present level in all domains, family concerns-priorities-resources, functional long-term goals (6-12 months), short-term objectives (SMART), strategies and activities, materials, who will do what and where (natural environments), frequency, start date, review dates, service coordinator, transition plan.","Example goal: 'Ravi will sit without support for 1 minute during play at home within 8 weeks'; strategy: supported sitting with toys in front, 10 minutes three times daily by mother.","Write goals that serve family priorities and fit routines, not isolated therapy tasks."]},
    {h:"Implementation, evaluation and record keeping", p:["Implement through home visits or centre sessions with parent coaching; demonstrate, let the parent practise, give feedback.","Monitor with daily or weekly charts kept by parents; review objectives monthly and the whole plan about every 6 months.","Evaluate child outcomes (goals achieved, change in DQ) and family outcomes (parent skills, confidence, access to services).","Records: case file with history, assessment reports, IEIP, progress notes, review reports, consent forms, referral letters; kept confidential and dated."]},
    {h:"Conclusion", p:["A family-centred IEIP translates assessment into a practical, shared plan; in the practical exam, the record, presentation and viva are judged on how clearly assessment links to goals and outcomes."]}
  ],
  tip:"Draw an IEIP table with columns: Domain, Present level, Long-term goal, Short-term objective, Strategy and materials, Responsible person, Review date, Outcome. Fill one sample row for motor and one for language.",
  evidence:[["Family-centred, routines-based intervention","Better family outcomes and child participation","Moderate"],["Early intervention for preterm infants","Improves cognitive outcomes in infancy and preschool","Moderate"],["Coaching parents within routines","Recommended practice; supports generalisation","Expert opinion"]],
  evidenceSource:"Spittle et al. Cochrane 2015; Dunst et al. 2007; DEC Recommended Practices 2014",
  outcomes:[["DASII or Portage re-assessment","Change in developmental level"],["Goal attainment scaling","Achievement of IEIP goals"],["Family outcome checklist","Parent skills, confidence and satisfaction"]],
  recent:["DEC Recommended Practices (2014) emphasise family-centred, routines-based planning and coaching, which match the IEIP practical format."],
  mnemonic:{word:"CPR", items:[["C","Concerns of the family"],["P","Priorities"],["R","Resources"]], extra:"Case history order: ANNPD = Antenatal, Natal, Neonatal, Post-natal, Developmental (plus family history)."},
  example:"A 15-month-old girl in Secunderabad, born at 32 weeks, has a corrected age of 13 months. DASII shows motor DQ 70 and mental DQ 85. The mother's priority is that she sits to eat with the family. The IEIP sets sitting and finger-feeding goals within meal and play routines, reviewed every month.",
  flags:["Use corrected age for preterm babies until 2 years","Seizures, regression, rapid head growth or failure to thrive: medical referral first","Obtain informed consent and keep records confidential","Do not write goals the family has not agreed to"],
  viva:[["What is an IFSP?","Individualised Family Service Plan: a written plan for an infant or toddler and family, listing present levels, family concerns, priorities and resources, outcomes, services and transition."],["How do you calculate developmental quotient?","Developmental age divided by chronological (corrected) age, multiplied by 100."],["What is the Routines-Based Interview?","A semi-structured family interview (McWilliam) that goes through daily routines to find functional priorities for goals."]],
  refs:[{b:"batshaw",ch:"Early intervention and the IFSP"},{b:"turnbull",ch:"Individualised planning with families"},{b:"dunst",ch:"Assessing family needs and resources"},{c:"Division for Early Childhood. DEC Recommended Practices in Early Intervention/Early Childhood Special Education 2014.", u:"https://www.dec-sped.org/dec-recommended-practices"}],
  keywords:"IEIP IFSP case history developmental assessment family assessment goals implementation evaluation record keeping practical",
  mcq:[["A preterm baby born at 28 weeks is now 6 months old. The corrected age is about:",["6 months","5 months","3 months","4 months"],2,"Born 12 weeks (3 months) early: 6 - 3 = 3 months corrected age."],["CPR in family assessment stands for:",["Concerns, priorities, resources","Child, parent, relatives","Cardio-pulmonary resuscitation","Care, play, routine"],0,"Family concerns, priorities and resources guide IEIP goals."]]
}
]);
